import { UNRESERVED_CHARS_SRC, buildUriPredicates } from "./rfc-3986.js";
//#region src/utils/rfc-3987.ts
const IRI_PREDICATES = buildUriPredicates({
	unreservedChars: `${UNRESERVED_CHARS_SRC}\\u00A0-\\uD7FF\\uF900-\\uFDCF\\uFDF0-\\uFFEF\\u{10000}-\\u{1FFFD}\\u{20000}-\\u{2FFFD}\\u{30000}-\\u{3FFFD}\\u{40000}-\\u{4FFFD}\\u{50000}-\\u{5FFFD}\\u{60000}-\\u{6FFFD}\\u{70000}-\\u{7FFFD}\\u{80000}-\\u{8FFFD}\\u{90000}-\\u{9FFFD}\\u{A0000}-\\u{AFFFD}\\u{B0000}-\\u{BFFFD}\\u{C0000}-\\u{CFFFD}\\u{D0000}-\\u{DFFFD}\\u{E1000}-\\u{EFFFD}`,
	privateQueryChars: "\\uE000-\\uF8FF\\u{F0000}-\\u{FFFFD}\\u{100000}-\\u{10FFFD}"
});
/** Tests a string against RFC 3987 §2.2 `IRI` — an absolute IRI with an optional fragment. */
const isValidIri = IRI_PREDICATES.isAbsolute;
/** Tests a string against RFC 3987 §2.2 `IRI-reference` — an `IRI` or an `irelative-ref`. */
const isValidIriReference = IRI_PREDICATES.isReference;
//#endregion
export { isValidIri, isValidIriReference };
